-- Q5 the 110 hit EINs: every AUTO_REVOCATIONS row (any year), the older REVOCATION copy, Pub 78, and the EO BMF today
WITH h(EIN) AS (SELECT * FROM VALUES ('043669343'),('043680704'),('133131470'),('133459199'),('133465221'),('201886455'),('202079820'),('203693012'),('222458532'),('223183851'),('232458755'),('232549367'),('237408472'),('263290073'),('270710950'),('271710966'),('272343783'),('274029245'),('300162286'),('301172130'),('306174993'),('310939288'),('311551316'),('320124748'),('330874959'),('341436436'),('352581033'),('363707624'),('383327648'),('420257915'),('451482340'),('460956697'),('461218702'),('461318831'),('461347832'),('463312196'),('465158124'),('465296804'),('470439999'),('470560720'),('472541624'),('472602205'),('473081161'),('473819764'),('475089353'),('510668420'),('521273277'),('541061140'),('561550544'),('581923886'),('593543568'),('611533759'),('650798174'),('746052266'),('753040686'),('760074326'),('770117649'),('770243483'),('770414181'),('770465706'),('770560970'),('800863806'),('811639587'),('815447799'),('820868244'),('822649136'),('823194494'),('824424844'),('831633132'),('832015730'),('832222109'),('842673216'),('844010895'),('845056982'),('851525069'),('852306203'),('852353966'),('852744948'),('853464860'),('861946099'),('862259094'),('862424394'),('862561630'),('871986069'),('872718363'),('872970581'),('873918626'),('874076141'),('874189293'),('874240573'),('874262068'),('874371945'),('880712878'),('881079353'),('882122382'),('882629150'),('882899842'),('883776302'),('883920364'),('883972917'),('883990506'),('884159702'),('900532866'),('900684329'),('900720587'),('900825114'),('920377828'),('921002356'),('946105053'),('953133368')),
a AS (SELECT EIN, COUNT(*) n_auto, MIN(REVOCATION_DATE) d0, MAX(REVOCATION_DATE) d1, MAX(REINSTATEMENT_DATE) rd_auto, MAX(REVOCATION_POSTING_DATE) pd_auto
      FROM LIBRARY_MARTS.ECONOMICS.ECONOMICS__FED_IRS_AUTO_REVOCATIONS WHERE EIN IN (SELECT EIN FROM h) GROUP BY EIN),
o AS (SELECT EIN, COUNT(*) n_old, MAX(REVOCATION_DATE) d_old, MAX(NULLIF(TRIM(REINSTATEMENT_DATE), '')) rd_old
      FROM LIBRARY_MARTS.ECONOMICS.ECONOMICS__FED_IRS_REVOCATION WHERE EIN IN (SELECT EIN FROM h) GROUP BY EIN),
p AS (SELECT EIN, COUNT(*) n_p78, MAX(DEDUCTIBILITY_STATUS) ded FROM LIBRARY_MARTS.ECONOMICS.ECONOMICS__FED_IRS_PUB78_ELIGIBLE_DONEES WHERE EIN IN (SELECT EIN FROM h) GROUP BY EIN),
b AS (SELECT EIN, COUNT(*) n_bmf, MAX(RULING_YYYYMM) ruling, MAX(STATUS_CODE) st FROM LIBRARY_MARTS.CORPORATE_REGISTRY.CORPORATE_REGISTRY__FED_IRS_EO_BMF WHERE EIN IN (SELECT EIN FROM h) GROUP BY EIN)
SELECT h.EIN, a.n_auto, a.d0, a.d1, a.rd_auto, a.pd_auto, o.n_old, o.d_old, o.rd_old, p.n_p78, p.ded, b.n_bmf, b.ruling, b.st
FROM h LEFT JOIN a ON a.EIN = h.EIN LEFT JOIN o ON o.EIN = h.EIN LEFT JOIN p ON p.EIN = h.EIN LEFT JOIN b ON b.EIN = h.EIN
ORDER BY h.EIN;
